    ("d2_aili_craft", 59, "say", "bubi", "default", "먀옹.", "Meow.", "grade >= perfect", "", ""),
    ("d2_aili_craft", 60, "say", "aili", "default", "실력이 꽤 괜찮나 보네.\n부비까지 만족시키다니.", "Your skills must be decent.\nSatisfying even Bubi, of all customers.", "grade >= perfect", "", ""),
